def source(id,title,url,type,supports,limits,**extra):
    assert id not in {x['id'] for x in sources},id
    sources.append(dict(id=id,title=title,url=url,type=type,checked_at='2026-10-22',supports=supports,limits=limits,**extra))
entries=[
 ('A33','Microsoft: Progress controls','https://learn.microsoft.com/en-us/windows/apps/develop/ui/controls/progress-controls','Primaire platformrichtlijn','Bepaalde/onbepaalde voortgang en uitleg over de lopende activiteit.','Windows-patroon. Ring/balk is geen universele cross-platform semantische regel.'),
 ('A34','W3C WCAG 2.2 Understanding 4.1.3: Status Messages','https://www.w3.org/WAI/WCAG22/Understanding/status-messages.html','Primaire toelichting bij WCAG-succescriterium','Status zonder focusverplaatsing toegankelijk melden, inclusief incidentele voortgang en accessibility-API’s.','Informatieve toelichting; native app moet de eigen platformroute aantonen. Geen verplichting iedere procentstap uit te spreken.'),
 ('A35','Harrison e.a. (UIST 2007): Rethinking the Progress Bar','https://www.chrisharrison.net/projects/progressbars/ProgBarHarrison.pdf','Primair gepubliceerd gebruikersonderzoek','Verschillende voortgangscurves beïnvloeden ervaren duur; 22 deelnemers, vaste duur 5,5 seconden.','Onderzoekslabpopulatie en korte vergelijkingen. Geen langdurige BIM-taak, werkelijke versnelling of rechtvaardiging voor onjuiste percentages.'),
 ('A36','Google web.dev: Optimize long tasks','https://web.dev/articles/optimize-long-tasks','Primaire browser-/performancedocumentatie','Lange main-threadtaken blokkeren interactie; opsplitsen/yielding als oplossingsrichting.','50 ms is een webmeetdefinitie. Geen universele native prestatiegrens of gemeten OpenAEC-resultaat.'),
 ('A37','Mozilla MDN: beforeunload','https://developer.mozilla.org/en-US/docs/Web/API/Window/beforeunload_event','Primaire browserimplementatiedocumentatie','Beforeunload is niet betrouwbaar als laatste opslagmoment, vooral mobiel.','Gedrag blijft browser-/platformafhankelijk; een sluitwaarschuwing kan nog nuttig zijn, maar is geen herstelstrategie.'),
 ('A38','Qt QSaveFile','https://doc.qt.io/qt-6/qsavefile.html','Primaire toolkitdocumentatie','Tijdelijk schrijven en commit/vervanging; direct-write-fallback verliest bescherming tegen gedeeltelijk overschrijven.','Ontwerpprecedent uit een andere toolkit. Geen voorstel voor Qt-migratie of garantie voor OpenAEC-filesystems.'),
 ('A39','Rust std::fs::rename','https://doc.rust-lang.org/std/fs/fn.rename.html','Primaire taal-/bibliotheekdocumentatie','Vervanging en platform-/mountvoorwaarden bij rename.','Op zichzelf geen volledige crash-/stroomuitvalbestendigheidstest of netwerksharegarantie.'),
 ('A40','Tauri Window.destroy','https://v2.tauri.app/reference/javascript/api/namespacewindow/#destroy','Primaire toolkitdocumentatie','Destroy forceert sluiten zonder opnieuw closeRequested uit te sturen.','Actuele Tauri 2-documentatie, geen daadwerkelijk gesloten venster in onze proef.'),
 ('A41','Autodesk: Is it possible to autosave projects in Revit','https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/Does-an-Autosave-option-exist-for-Revit.html','Primaire productsupport / tegenvoorbeeld','Revit beschrijft complexiteit/performance bij autosave en onderscheid met herinneringen en back-ups.','Productspecifieke supportpagina. Zoekresultaat gaf inhoud; geopende pagina leverde geen extra tekst. Geen argument tegen ieder automatisch herstel.'),
 ('A42','LibreCAD-forum: files not being saved','https://forum.librecad.org/files-not-being-saved-td5717999.html','Historische openbare gebruikerservaring','Verwarring tussen autosave/herstelbestanden, doelpad en handmatig opslaan.','Oude versies, oorzaak niet onafhankelijk gereproduceerd; niet als actuele LibreCAD-bug of gebruikersfout vastgesteld.'),
 ('A43','Reddit r/SolidWorks: Longest wait for a busy command','https://www.reddit.com/r/SolidWorks/comments/1fe8kmb/','Openbare gebruikersdiscussie met tegenvoorbeelden','Zowel opgegeven taken als later voltooide lange taken; onduidelijkheid over wachten versus afsluiten.','Anekdotisch, deels humor. Geen representatieve prevalentie, productbenchmark of aanbevolen time-out.'),
 ('A44','iced 0.13.1 Task::abortable en Handle','https://github.com/iced-rs/iced/blob/9bfbd7cda79aceef2d115b8bb35e8f3257dcabf2/runtime/src/task.rs#L173','Gepinde primaire toolkitbron','Bestaande abortable taskstream en abort-handle in de gebruikte frameworkversie.','Geen automatische rollback van externe effecten of garantie dat los werkende workers eindigen.'),
 ('A45','Tauri: Calling Rust / Async Commands','https://v2.tauri.app/develop/calling-rust/#async-commands','Primaire toolkitdocumentatie','Uitvoeringsverschil tussen async en gewone commands; zwaar werk moet de UI niet blokkeren.','Geen volledige audit van alle OpenAEC-commands. Async betekent geen onbeperkte CPU-capaciteit of automatische annulering.'),
 ('A46','WHATWG HTML: Downloading resources','https://html.spec.whatwg.org/multipage/links.html#downloading-resources','Primaire levende webstandaard','Browser beheert de downloadprocedure met aanvullende stappen en mogelijke afbreekmomenten.','Geen geteste download in deze ronde; een anchor-click levert de app hier geen schijfwritebevestiging.'),
 ('A47','Mozilla MDN: AbortController.abort','https://developer.mozilla.org/en-US/docs/Web/API/AbortController/abort','Primaire browserimplementatiedocumentatie','Abort ondersteunt onder meer fetch, responseconsumptie en streams.','Geen algemene garantie voor het stoppen of terugdraaien van native of onafhankelijke berekeningen.'),
 ('A48','Chrome: Page Lifecycle API','https://developer.chrome.com/docs/web-platform/page-lifecycle-api','Primaire browserplatformdocumentatie','Sessie-einde is niet altijd detecteerbaar; verborgen/frozen/terminated vragen eigen omgang met staat.','Browseradvies, geen universele desktop-lifecycle. Werkelijke opslag en herstel moeten afzonderlijk worden getest.')]
for entry in entries:source(*entry)
