def finding(id,module,title,claim,priority,evidence,sids,recommendation,validation,limits,locations):
    assert id not in {f['id'] for f in findings},id
    findings.append(dict(id=id,module=module,title=title,claim=claim,priority=priority,evidence_status=evidence,source_ids=sids,recommendation=recommendation,validation=validation,limits=limits,code_locations=locations,status='proposal'))
finding('UI-016','05','Koppel opslagstatus aan de geschreven revisie','De gepinde savecallback markeert na await onvoorwaardelijk schoon; in de geïsoleerde proef bleef actuele versie 2 bestaan terwijl alleen payload 1 was geschreven.','P0','Exacte callbackbody uitgevoerd met gecontroleerde in-memory schrijfvertraging',['R23','R29'],'Bewaar document- en opslagrevisie; wis dirty alleen voor bevestigde revisie en controleer de schrijfvolgorde per document.',['Save vertragen, tussentijds bewerken en revisie/payload/dirty vergelijken.','Overlappende saves omgekeerd voltooien; end-to-end toetsen of onderliggende lagen dit scenario voorkomen.'],'Geen echte schijfwrite of aangetoonde verloren productiegegevens; serializer/store/I/O zijn stubs.',['Calc useFileOperations.ts:98','Calc documentSlice.ts:91'])
finding('UI-017','05','Laat sluiten alle gewijzigde documenten afhandelen','De gepinde sluitcallback vraagt over het eerste dirty document, slaat via de actieve-tabroute op en kan na één beslissing destroy aanroepen terwijl een tweede document dirty blijft.','P0','Gepinde bron + uitgevoerde meerdocumentscenario’s + primaire destroy-semantiek',['R22','R23','A40'],'Maak een sluitplan met expliciete document-ID’s en bevestiging/resultaat per gewijzigd document; sluit pas als alle beslissingen verwerkt zijn.',['Twee dirty documenten, beide actieve tabs, Save/Discard/Cancel.','Schrijffout en geannuleerd Save As houden alle nog relevante documenten bereikbaar.'],'Geen echt venster gesloten; geen integratietest met eventuele overige productlagen.',['Calc App.tsx:337','Calc useFileOperations.ts:98'])
finding('UI-018','05','Onderscheid autosave, herstelkopie en hoofdproject','Calc autosave schrijft alleen het actieve gewijzigde desktopdocument met bestaand pad; dat dekt nieuwe naamloze of alle achtergrondtabbladen niet.','P1','Statische routecontrole + openbare verwachtingstegenvoorbeelden',['R22','A41','A42','A37'],'Definieer aparte beloften en zichtbare tijden/locaties voor opslaan, herstel en synchronisatie; bied herstel als kopie aan.',['Nieuw document zonder pad en achtergrondtab na onderbreking.','Herstelkopie vergelijken met hoofdproject zonder stil overschrijven.'],'Geen volledige audit van andere opslag-/herstelroutes in alle apps. Interval is bestaande keuze, geen gevalideerd optimum.',['Calc App.tsx:317'])
finding('UI-019','05','Bevestig de opslaguitkomst die de app werkelijk kent','Browserfallback start een download en markeert schoon; native documentwrapper en voorkeuren gebruiken verschillende zichtbare schrijfroutes.','P1','Concrete code + primaire download-/opslagdocumentatie',['R20','R23','R24','A38','A39','A46'],'Gebruik passende bevestiging per opslagmedium; toets temp/commit, fouten en behoud van de laatste goede versie op ondersteunde locaties.',['Download annuleren/blokkeren; UI-tekst en herstel controleren.','Schijf vol, rechtenfout en onderbreking tijdens schrijven op echte doelplatformen.'],'Geen bewezen plugin-atomiciteitsfout; geen download of bestand beschadigd in deze ronde.',['Calc useFileOperations.ts:134','Calc nativeFileService.ts:130','crates/openaec-ui/src/model.rs:200'])
finding('UI-020','06','Definieer annuleren tot aan het domeinwerk','Een balkstijl of optionele onCancel-callback bewijst geen gestopte import; iced 0.13.1 heeft wel al een abortable taskstream.','P1','Statische component- en gepinde frameworkinspectie',['R27','R28','R01','A44','A47'],'Voer taak-ID, document/revisie, annuleringsaanvraag, bevestiging en eindresultaat in het voorgestelde taakcontract op.',['Annuleer voor/tijdens/na commit en controleer echte werk-/schrijfuitkomst.','Negeer late resultaten van oude taak/revisie; behoud gedeeltelijke uitvoer zichtbaar.'],'Geen annuleringsintegratie getest; geen claim dat framework geen annulering kan.',['Calc ProgressModal.tsx:14','crates/openaec-ui/src/widgets.rs:219','iced runtime/src/task.rs:173'])
finding('UI-021','06','Profileer volledige datakopieën en synchrone voorbereiding','Calc serialiseert vóór await, kopieert complete history-items en berekent logische rij-offsets; dit zijn mogelijke knelpunten naast virtueel renderen.','P1','Concrete profileringsplaatsen, geen gemeten vertraging',['R23','R25','R26','R14','A36','A45'],'Meet invoerblokkade, tijd tot bruikbaar beeld, geheugentop en annuleringslatentie met representatieve bestanden/hardware.',['Neem trace van opslaan, undo en scrollen met normale/zware bestanden.','Controleer of UI feedback kan tekenen en invoer kan verwerken tijdens voorbereiding.'],'Geen benchmark of bewezen performance-incident. De webdefinitie 50 ms is geen algemene native eis.',['Calc useFileOperations.ts:105','Calc fileService.ts:40','Calc historySlice.ts:29','Calc useGridVirtualizer.ts:20'])
finding('UI-022','06','Maak voortgang inhoudelijk en toegankelijk','De 0.4-vormafspraak specificeert een balk, maar geen gedeeld bewijs voor fase/noemer, taakuitkomst en assistieve statusmelding.','P1','Ontwerpvoorstel gebaseerd op primaire documentatie en begrensd gebruikersonderzoek',['R07','R28','A33','A34','A35','A43'],'Toon afgebakende fasen, alleen onderbouwde percentages en betekenisvolle meldmomenten zonder focusdiefstal.',['Controleer onbekend totaal, fasewisseling en 100%-moment.','Schermlezer, gereduceerde beweging en een gebruiker die elders werkt.'],'Geen universeel beste animatie of gemeten OpenAEC-wachttijdvoorkeur vastgesteld.',['design/ontwerp-0.4/04-componenten.md:59','crates/openaec-ui/src/widgets.rs:219'])
finding('UI-023','05','Leg undo-scope en taakgrenzen vast','De gelezen Calc-historySlice bevat items-snapshots en omschrijvingen; algemene afspraken over domeintaak, document en focus zijn daarmee niet aangetoond.','P1','Broninspectie + contractvoorstel',['R25','R12','R13'],'Specificeer één logische undo-stap per taak, documentcontext, tekstfocus en niet-herstelbare acties; houd crashherstel afzonderlijk.',['Plakbereik, bulkactie en drag elk terugdraaien.','Wissel document/tekstfocus en controleer benoemde Undo/Redo-uitkomst.'],'Geen volledige audit van alle history-aanroepen; geen aangetoonde verkeerde undo in productie.',['Calc historySlice.ts:23'])

